import json
schema_req = {'id': str, 'title': str, 'ladder_rank': int}
def valid(rec):
    try: r = json.loads(rec)
    except Exception: return False, 'unparseable'
    for k, t in schema_req.items():
        if k not in r: return False, 'missing ' + k
        if not isinstance(r[k], t): return False, 'bad type ' + k
    return True, 'ok'
print(valid('{"id":"a","title":"b","ladder_rank":2}'))
print(valid('{"id":"a","title":"b"}'))

