import hashlib, gzip, io
chunks = {'c1': b'line1\nline2\n', 'c2': b'line1\nline2\nCORRUPT'}
manifest = {k: hashlib.sha256(v).hexdigest() for k, v in chunks.items()}
manifest['c2'] = hashlib.sha256(b'line1\nline2\n').hexdigest()  # recorded good value
for name, data in chunks.items():
    ok = hashlib.sha256(data).hexdigest() == manifest[name]
    print(name, 'PASS' if ok else 'FAIL -> quarantine')

